=== FILE: apb_regs.v ===
`timescale 1ns/1ps
`default_nettype none

// apb_regs: four 32-bit read/write registers behind an APB4 subordinate port.
// Implements interface_spec.md per microarchitecture.md.
//  - Zero wait states: pready tied high.
//  - access = psel && penable is the completing cycle; writes commit on its edge.
//  - Mapped: paddr[1:0] == 0 and paddr < 0x10. Everything else: pslverr.
//  - prdata and pslverr are zero outside the access phase.
//  - presetn: synchronous, active low; all registers reset to zero.
module apb_regs #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer DATA_WIDTH = 32
) (
    input  wire                    pclk,
    input  wire                    presetn,
    input  wire [ADDR_WIDTH-1:0]   paddr,
    input  wire                    psel,
    input  wire                    penable,
    input  wire                    pwrite,
    input  wire [DATA_WIDTH-1:0]   pwdata,
    input  wire [DATA_WIDTH/8-1:0] pstrb,
    output wire [DATA_WIDTH-1:0]   prdata,
    output wire                    pready,
    output wire                    pslverr
);

  localparam integer NBYTES = DATA_WIDTH / 8;

  // Register file: four separate flops.
  reg  [DATA_WIDTH-1:0] reg0;
  reg  [DATA_WIDTH-1:0] reg1;
  reg  [DATA_WIDTH-1:0] reg2;
  reg  [DATA_WIDTH-1:0] reg3;

  // Next values: byte merge of pwdata into the old value under pstrb.
  wire [DATA_WIDTH-1:0] reg0_nxt;
  wire [DATA_WIDTH-1:0] reg1_nxt;
  wire [DATA_WIDTH-1:0] reg2_nxt;
  wire [DATA_WIDTH-1:0] reg3_nxt;

  // Transfer decode.
  wire       access    = psel && penable;
  wire       mapped    = (paddr[1:0] == 2'b00) &&
                         (paddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});
  wire       wr_access = access && pwrite && mapped;
  wire       rd_access = access && !pwrite && mapped;
  wire [1:0] idx       = paddr[3:2];

  wire we0 = wr_access && (idx == 2'd0);
  wire we1 = wr_access && (idx == 2'd1);
  wire we2 = wr_access && (idx == 2'd2);
  wire we3 = wr_access && (idx == 2'd3);

  genvar b;
  generate
    for (b = 0; b < NBYTES; b = b + 1) begin : g_merge
      assign reg0_nxt[8*b +: 8] = pstrb[b] ? pwdata[8*b +: 8] : reg0[8*b +: 8];
      assign reg1_nxt[8*b +: 8] = pstrb[b] ? pwdata[8*b +: 8] : reg1[8*b +: 8];
      assign reg2_nxt[8*b +: 8] = pstrb[b] ? pwdata[8*b +: 8] : reg2[8*b +: 8];
      assign reg3_nxt[8*b +: 8] = pstrb[b] ? pwdata[8*b +: 8] : reg3[8*b +: 8];
    end
  endgenerate

  // Register block: reset value, or load enable.
  always @(posedge pclk) begin
    if (!presetn) begin
      reg0 <= {DATA_WIDTH{1'b0}};
      reg1 <= {DATA_WIDTH{1'b0}};
      reg2 <= {DATA_WIDTH{1'b0}};
      reg3 <= {DATA_WIDTH{1'b0}};
    end else begin
      if (we0) reg0 <= reg0_nxt;
      if (we1) reg1 <= reg1_nxt;
      if (we2) reg2 <= reg2_nxt;
      if (we3) reg3 <= reg3_nxt;
    end
  end

  // Read multiplexer.
  reg [DATA_WIDTH-1:0] rd_mux;
  always @(*) begin
    case (idx)
      2'd0:    rd_mux = reg0;
      2'd1:    rd_mux = reg1;
      2'd2:    rd_mux = reg2;
      2'd3:    rd_mux = reg3;
      default: rd_mux = {DATA_WIDTH{1'b0}};
    endcase
  end

  assign prdata  = rd_access ? rd_mux : {DATA_WIDTH{1'b0}};
  assign pslverr = access && !mapped;
  assign pready  = 1'b1;

`ifdef FORMAL
  // ---------------------------------------------------------------------
  // Formal properties. Decode and byte rules are written independently of
  // the design's 'mapped' and merge logic above.
  // ---------------------------------------------------------------------
  reg f_past_valid;
  initial f_past_valid = 1'b0;
  always @(posedge pclk) f_past_valid <= 1'b1;

  // Previous-cycle copies (used instead of $past).
  reg                  f_prev_presetn;
  reg                  f_prev_psel;
  reg                  f_prev_penable;
  reg                  f_prev_pwrite;
  reg [ADDR_WIDTH-1:0] f_prev_paddr;
  reg [DATA_WIDTH-1:0] f_prev_pwdata;
  reg [NBYTES-1:0]     f_prev_pstrb;
  reg [DATA_WIDTH-1:0] f_prev_reg0;
  reg [DATA_WIDTH-1:0] f_prev_reg1;
  reg [DATA_WIDTH-1:0] f_prev_reg2;
  reg [DATA_WIDTH-1:0] f_prev_reg3;

  always @(posedge pclk) begin
    f_prev_presetn <= presetn;
    f_prev_psel    <= psel;
    f_prev_penable <= penable;
    f_prev_pwrite  <= pwrite;
    f_prev_paddr   <= paddr;
    f_prev_pwdata  <= pwdata;
    f_prev_pstrb   <= pstrb;
    f_prev_reg0    <= reg0;
    f_prev_reg1    <= reg1;
    f_prev_reg2    <= reg2;
    f_prev_reg3    <= reg3;
  end

  // Manager (requester) assumptions.
  always @(*) begin
    // Reset is active on the first cycle.
    if (!f_past_valid) assume(!presetn);
    // No transfer in reset.
    if (!presetn) assume(!psel);
    // penable only with psel.
    if (!psel) assume(!penable);
    // Reads carry no strobes.
    if (psel && !pwrite) assume(pstrb == {NBYTES{1'b0}});
    // An access phase follows a setup phase with a stable request.
    if (psel && penable)
      assume(f_past_valid && f_prev_presetn && f_prev_psel && !f_prev_penable &&
             (paddr == f_prev_paddr) && (pwrite == f_prev_pwrite) &&
             (pwdata == f_prev_pwdata) && (pstrb == f_prev_pstrb));
    // A setup phase is followed by its access phase (out of reset).
    if (f_past_valid && f_prev_presetn && presetn && f_prev_psel && !f_prev_penable)
      assume(psel && penable);
  end

  // Independent decode and read expectation.
  wire                  f_access = psel && penable;
  wire                  f_mapped = (paddr[1:0] == 2'b00) && (paddr < 16);
  wire [DATA_WIDTH-1:0] f_rd_expect =
      (paddr == 0)  ? reg0 :
      (paddr == 4)  ? reg1 :
      (paddr == 8)  ? reg2 :
      (paddr == 12) ? reg3 : {DATA_WIDTH{1'b0}};

  // Response properties.
  always @(*) begin
    assert(pready);
    if (!f_access) begin
      assert(prdata == {DATA_WIDTH{1'b0}});
      assert(!pslverr);
    end else begin
      assert(pslverr == !f_mapped);
      if (f_mapped && !pwrite)
        assert(prdata == f_rd_expect);
      else
        assert(prdata == {DATA_WIDTH{1'b0}});
    end
  end

  // Registers are zero after reset.
  always @(*) begin
    if (f_past_valid && !f_prev_presetn) begin
      assert(reg0 == {DATA_WIDTH{1'b0}});
      assert(reg1 == {DATA_WIDTH{1'b0}});
      assert(reg2 == {DATA_WIDTH{1'b0}});
      assert(reg3 == {DATA_WIDTH{1'b0}});
    end
  end

  // Each byte changes only in a mapped write access to its register with its
  // strobe set, and then to the written byte.
  wire f_prev_wr = f_past_valid && f_prev_presetn && f_prev_psel &&
                   f_prev_penable && f_prev_pwrite;

  genvar fb;
  generate
    for (fb = 0; fb < NBYTES; fb = fb + 1) begin : g_f_lane
      always @(*) begin
        if (f_past_valid && f_prev_presetn) begin
          if (f_prev_wr && f_prev_pstrb[fb] && (f_prev_paddr == 0))
            assert(reg0[8*fb +: 8] == f_prev_pwdata[8*fb +: 8]);
          else
            assert(reg0[8*fb +: 8] == f_prev_reg0[8*fb +: 8]);

          if (f_prev_wr && f_prev_pstrb[fb] && (f_prev_paddr == 4))
            assert(reg1[8*fb +: 8] == f_prev_pwdata[8*fb +: 8]);
          else
            assert(reg1[8*fb +: 8] == f_prev_reg1[8*fb +: 8]);

          if (f_prev_wr && f_prev_pstrb[fb] && (f_prev_paddr == 8))
            assert(reg2[8*fb +: 8] == f_prev_pwdata[8*fb +: 8]);
          else
            assert(reg2[8*fb +: 8] == f_prev_reg2[8*fb +: 8]);

          if (f_prev_wr && f_prev_pstrb[fb] && (f_prev_paddr == 12))
            assert(reg3[8*fb +: 8] == f_prev_pwdata[8*fb +: 8]);
          else
            assert(reg3[8*fb +: 8] == f_prev_reg3[8*fb +: 8]);
        end
      end
    end
  endgenerate

  // Covers: each register written and read back non-zero, error responses,
  // and a partial-strobe write.
  genvar fr;
  generate
    for (fr = 0; fr < 4; fr = fr + 1) begin : g_f_cover
      always @(*) cover(f_access && !pwrite && (paddr == 4*fr) &&
                        (prdata != {DATA_WIDTH{1'b0}}));
    end
  endgenerate

  always @(*) cover(f_access && pwrite && !f_mapped);
  always @(*) cover(f_access && !pwrite && !f_mapped);
  always @(*) cover(f_prev_wr && (f_prev_paddr == 8) && (f_prev_pstrb == 4'b0101) &&
                    (reg2 != {DATA_WIDTH{1'b0}}));
`endif

endmodule

`default_nettype wire
=== END FILE ===
