`default_nettype none

// Self-checking directed testbench for apb_regs.
// Inputs change after the falling edge; outputs are sampled 1 ns later,
// well before the next rising edge.
module apb_regs_tb;

  reg         pclk;
  reg         presetn;
  reg  [7:0]  paddr;
  reg         psel;
  reg         penable;
  reg         pwrite;
  reg  [31:0] pwdata;
  reg  [3:0]  pstrb;
  wire [31:0] prdata;
  wire        pready;
  wire        pslverr;

  integer passed;
  integer failed;
  integer rc;
  reg [4:0]  k;
  reg [31:0] m0;
  reg [31:0] m1;
  reg [31:0] m2;
  reg [31:0] m3;
  reg [8*64-1:0] nonce;

  apb_regs #(.ADDR_WIDTH(8), .DATA_WIDTH(32)) dut (
    .pclk    (pclk),
    .presetn (presetn),
    .paddr   (paddr),
    .psel    (psel),
    .penable (penable),
    .pwrite  (pwrite),
    .pwdata  (pwdata),
    .pstrb   (pstrb),
    .prdata  (prdata),
    .pready  (pready),
    .pslverr (pslverr)
  );

  initial pclk = 1'b0;
  always #5 pclk = ~pclk;

  // ---------------- model ----------------
  function is_mapped;
    input [7:0] a;
    begin
      is_mapped = (a[1:0] == 2'b00) && (a < 8'h10);
    end
  endfunction

  function [31:0] model_get;
    input [1:0] idx;
    begin
      case (idx)
        2'd0:    model_get = m0;
        2'd1:    model_get = m1;
        2'd2:    model_get = m2;
        default: model_get = m3;
      endcase
    end
  endfunction

  function [31:0] merge;
    input [31:0] old;
    input [31:0] d;
    input [3:0]  s;
    begin
      merge[7:0]   = s[0] ? d[7:0]   : old[7:0];
      merge[15:8]  = s[1] ? d[15:8]  : old[15:8];
      merge[23:16] = s[2] ? d[23:16] : old[23:16];
      merge[31:24] = s[3] ? d[31:24] : old[31:24];
    end
  endfunction

  task model_set;
    input [1:0]  idx;
    input [31:0] v;
    begin
      case (idx)
        2'd0:    m0 = v;
        2'd1:    m1 = v;
        2'd2:    m2 = v;
        default: m3 = v;
      endcase
    end
  endtask

  // ---------------- checks ----------------
  task chk32;
    input [31:0] act;
    input [31:0] expv;
    input integer id;
    begin
      if (act === expv) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("check %0d failed at %0t: got 0x%08h, expected 0x%08h", id, $time, act, expv);
      end
    end
  endtask

  task chk1;
    input act;
    input expv;
    input integer id;
    begin
      if (act === expv) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("check %0d failed at %0t: got %b, expected %b", id, $time, act, expv);
      end
    end
  endtask

  task chk_quiet;
    input integer id;
    begin
      chk32(prdata, 32'h00000000, id);
      chk1(pslverr, 1'b0, id);
    end
  endtask

  // ---------------- bus tasks ----------------
  task apb_write;
    input [7:0]  a;
    input [31:0] d;
    input [3:0]  s;
    input integer id;
    reg err;
    begin
      err = ~is_mapped(a);
      // setup phase
      @(negedge pclk);
      psel = 1'b1; penable = 1'b0; pwrite = 1'b1;
      paddr = a; pwdata = d; pstrb = s;
      #1;
      chk_quiet(id * 10 + 1);
      // access phase
      @(negedge pclk);
      penable = 1'b1;
      #1;
      chk1(pready, 1'b1, id * 10 + 2);
      chk1(pslverr, err, id * 10 + 3);
      chk32(prdata, 32'h00000000, id * 10 + 4);
      @(posedge pclk);
      if (!err) model_set(a[3:2], merge(model_get(a[3:2]), d, s));
    end
  endtask

  task apb_read;
    input [7:0] a;
    input integer id;
    reg err;
    reg [31:0] expd;
    begin
      err  = ~is_mapped(a);
      expd = err ? 32'h00000000 : model_get(a[3:2]);
      // setup phase
      @(negedge pclk);
      psel = 1'b1; penable = 1'b0; pwrite = 1'b0;
      paddr = a; pwdata = 32'h00000000; pstrb = 4'h0;
      #1;
      chk_quiet(id * 10 + 1);
      // access phase
      @(negedge pclk);
      penable = 1'b1;
      #1;
      chk1(pready, 1'b1, id * 10 + 2);
      chk1(pslverr, err, id * 10 + 3);
      chk32(prdata, expd, id * 10 + 4);
      @(posedge pclk);
    end
  endtask

  // Idle cycles with junk on the request lines; nothing may happen.
  task idle;
    input integer cycles;
    input integer id;
    integer i;
    begin
      for (i = 0; i < cycles; i = i + 1) begin
        @(negedge pclk);
        psel = 1'b0; penable = 1'b0; pwrite = ~pwrite;
        paddr = 8'h04; pwdata = 32'hA5A5A5A5; pstrb = 4'hF;
        #1;
        chk_quiet(id * 10 + 5);
      end
    end
  endtask

  task do_reset;
    input integer id;
    begin
      @(negedge pclk);
      presetn = 1'b0; psel = 1'b0; penable = 1'b0; pwrite = 1'b0;
      paddr = 8'h00; pwdata = 32'h00000000; pstrb = 4'h0;
      repeat (3) begin
        @(negedge pclk);
        #1;
        chk_quiet(id * 10 + 6);
      end
      @(negedge pclk);
      presetn = 1'b1;
      m0 = 32'h00000000; m1 = 32'h00000000;
      m2 = 32'h00000000; m3 = 32'h00000000;
    end
  endtask

  task read_all;
    input integer id;
    begin
      apb_read(8'h00, id);
      apb_read(8'h04, id + 1);
      apb_read(8'h08, id + 2);
      apb_read(8'h0C, id + 3);
    end
  endtask

  task bad_access;
    input [7:0] a;
    input integer id;
    begin
      apb_write(a, 32'hFFFFFFFF, 4'hF, id);
      apb_read(a, id + 1);
    end
  endtask

  // ---------------- sequence ----------------
  initial begin
    passed  = 0;
    failed  = 0;
    rc      = 0;
    nonce   = 512'd0;
    presetn = 1'b0; psel = 1'b0; penable = 1'b0; pwrite = 1'b0;
    paddr   = 8'h00; pwdata = 32'h00000000; pstrb = 4'h0;
    m0 = 32'h00000000; m1 = 32'h00000000;
    m2 = 32'h00000000; m3 = 32'h00000000;
    k  = 5'd0;

    // Reset and reset values.
    do_reset(1);
    idle(2, 2);
    read_all(10);
    idle(1, 14);

    // Write then read every register, with idle gaps.
    apb_write(8'h00, 32'h01234567, 4'hF, 20); idle(1, 21); apb_read(8'h00, 22); idle(2, 23);
    apb_write(8'h04, 32'h89ABCDEF, 4'hF, 24); idle(1, 25); apb_read(8'h04, 26); idle(1, 27);
    apb_write(8'h08, 32'hF0E1D2C3, 4'hF, 28); idle(3, 29); apb_read(8'h08, 30); idle(1, 31);
    apb_write(8'h0C, 32'h5A6B7C8D, 4'hF, 32); idle(1, 33); apb_read(8'h0C, 34); idle(1, 35);
    read_all(36);  // idle junk writes must not have touched reg1

    // Back-to-back transfers.
    apb_write(8'h00, 32'hDEADBEEF, 4'hF, 40);
    apb_write(8'h04, 32'hCAFEF00D, 4'hF, 41);
    apb_write(8'h08, 32'h13579BDF, 4'hF, 42);
    apb_write(8'h0C, 32'h2468ACE0, 4'hF, 43);
    read_all(44);
    apb_write(8'h08, 32'h0BADF00D, 4'hF, 48);
    apb_read(8'h08, 49);
    apb_write(8'h08, 32'h600DCAFE, 4'hF, 50);
    apb_read(8'h08, 51);
    apb_read(8'h04, 52);
    idle(1, 53);

    // Partial writes: single lanes on reg1.
    apb_write(8'h04, 32'h00000000, 4'hF, 60);
    apb_write(8'h04, 32'h11111111, 4'b0001, 61); apb_read(8'h04, 62);
    apb_write(8'h04, 32'h22222222, 4'b0010, 63); apb_read(8'h04, 64);
    apb_write(8'h04, 32'h33333333, 4'b0100, 65); apb_read(8'h04, 66);
    apb_write(8'h04, 32'h44444444, 4'b1000, 67); apb_read(8'h04, 68);
    // Partial writes on reg0 and reg2.
    apb_write(8'h00, 32'hFFFFFFFF, 4'hF, 70);
    apb_write(8'h00, 32'h00000000, 4'b0101, 71); apb_read(8'h00, 72);
    apb_write(8'h02 + 8'h06, 32'hFFFFFFFF, 4'hF, 73);
    apb_write(8'h08, 32'h00000000, 4'b1010, 74); apb_read(8'h08, 75);
    idle(1, 76);

    // Every strobe pattern, including none, on reg3.
    for (k = 5'd0; k < 5'd16; k = k + 5'd1) begin
      apb_write(8'h0C, 32'h5A5A5A5A ^ {4{3'b000, k}}, k[3:0], 100 + {27'd0, k});
      apb_read(8'h0C, 200 + {27'd0, k});
    end
    idle(1, 299);

    // Known values before the PSLVERR tests.
    apb_write(8'h00, 32'h11112222, 4'hF, 300);
    apb_write(8'h04, 32'h33334444, 4'hF, 301);
    apb_write(8'h08, 32'h55556666, 4'hF, 302);
    apb_write(8'h0C, 32'h77778888, 4'hF, 303);

    // Misaligned addresses.
    bad_access(8'h01, 310); bad_access(8'h02, 312); bad_access(8'h03, 314);
    bad_access(8'h05, 316); bad_access(8'h06, 318); bad_access(8'h07, 320);
    bad_access(8'h09, 322); bad_access(8'h0A, 324); bad_access(8'h0B, 326);
    bad_access(8'h0D, 328); bad_access(8'h0E, 330); bad_access(8'h0F, 332);
    // Out of range, including addresses that alias in paddr[3:2].
    bad_access(8'h10, 340); bad_access(8'h14, 342); bad_access(8'h18, 344);
    bad_access(8'h1C, 346); bad_access(8'h20, 348); bad_access(8'h40, 350);
    bad_access(8'h80, 352); bad_access(8'hF0, 354); bad_access(8'hFC, 356);
    bad_access(8'h11, 358); bad_access(8'hFF, 360);
    // No register changed.
    read_all(370);

    // Mapped and unmapped back to back.
    apb_write(8'h08, 32'hA1B2C3D4, 4'hF, 380);
    apb_write(8'h09, 32'h00000000, 4'hF, 381);
    apb_read(8'h08, 382);
    apb_read(8'h18, 383);
    apb_read(8'h08, 384);
    idle(2, 385);

    // Reset again.
    do_reset(390);
    idle(1, 391);
    read_all(392);
    apb_write(8'h0C, 32'hFEEDFACE, 4'hF, 396);
    apb_read(8'h0C, 397);
    apb_read(8'h00, 398);
    idle(2, 399);

    // Verdict.
    rc = $value$plusargs("nirmaan_nonce=%s", nonce);
    if (rc == 0) nonce = 512'd0;
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

